  $trendMax = max(1, (int) $ordersTrend->max('value'));
  $trendPoints = $ordersTrend->values()->map(function ($item, $index) use ($trendMax) {
      $x = 3 + ($index * 94);
      $y = 160 - (($item['value'] / $trendMax) * 135);
      return ['x' => $x, 'y' => $y, 'value' => $item['value']];
  });
  $trendLine = $trendPoints->map(fn ($point) => $point['x'].','.$point['y'])->implode(' ');
  $trendArea = '3,160 '.$trendLine.' 473,160';
@endphp
